import{_ as a,o as t,c as o,a2 as d}from"./chunks/framework.XctAhZuT.js";const u=JSON.parse('{"title":"架构总览","description":"Turna 客户端采用 Clean Architecture 风格分层，并使用 Provider、ChangeNotifier、GetIt / Injectable 和 Auto Route。分层目标是限制数据所有权和依赖方向，不是增加形式…","frontmatter":{"description":"Turna 客户端采用 Clean Architecture 风格分层，并使用 Provider、ChangeNotifier、GetIt / Injectable 和 Auto Route。分层目标是限制数据所有权和依赖方向，不是增加形式…"},"headers":[],"relativePath":"developer/architecture.md","filePath":"developer/architecture.md","lastUpdated":1790697640000}'),n={name:"developer/architecture.md"};function i(c,e,r,s,l,p){return t(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h1><p>Turna 客户端采用 Clean Architecture 风格分层，并使用 Provider、ChangeNotifier、GetIt / Injectable 和 Auto Route。分层目标是限制数据所有权和依赖方向，不是增加形式目录。</p><h2 id="目录职责" tabindex="-1">目录职责 <a class="header-anchor" href="#目录职责" aria-label="Permalink to &quot;目录职责&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lib/</span></span>
<span class="line"><span>  application/   状态容器、应用服务、工作流编排</span></span>
<span class="line"><span>  core/          FSRS、语言检测、纯函数与基础策略</span></span>
<span class="line"><span>  courses/       课程 loader 与 validator</span></span>
<span class="line"><span>  data/          drift 数据库、DAO、Repository 实现</span></span>
<span class="line"><span>  di/            GetIt / Injectable 注册</span></span>
<span class="line"><span>  domain/        不可变领域模型与 Repository 接口</span></span>
<span class="line"><span>  routing/       Auto Route 与启动守卫</span></span>
<span class="line"><span>  service/       启动、导出、远端备份（WebDAV）与生命周期服务</span></span>
<span class="line"><span>  views/         页面与组件</span></span></code></pre></div><h2 id="依赖方向" tabindex="-1">依赖方向 <a class="header-anchor" href="#依赖方向" aria-label="Permalink to &quot;依赖方向&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>views</span></span>
<span class="line"><span>  -&gt; application</span></span>
<span class="line"><span>  -&gt; domain &lt;- data</span></span>
<span class="line"><span>  -&gt; core</span></span>
<span class="line"><span></span></span>
<span class="line"><span>application -&gt; domain / core</span></span>
<span class="line"><span>data -&gt; domain</span></span>
<span class="line"><span>domain -&gt; no UI dependency</span></span></code></pre></div><h3 id="硬禁止" tabindex="-1">硬禁止 <a class="header-anchor" href="#硬禁止" aria-label="Permalink to &quot;硬禁止&quot;">​</a></h3><p>这些不是风格建议，由 <code>test/architecture/layering_guard_test.dart</code> 逐文件强制，失败即层边界已破：</p><table tabindex="0"><thead><tr><th>方向</th><th>判定</th></tr></thead><tbody><tr><td><code>views → data</code></td><td>禁止。必须经 application 服务或 domain 仓库接口。</td></tr><tr><td><code>application → data</code></td><td>硬禁止。DAO / Repository 一律经 <code>domain/repositories/</code> 消费。</td></tr><tr><td><code>application</code> / <code>domain</code> / <code>core</code> / <code>service</code> → <code>views</code></td><td>禁止（<code>di/</code> 装配模块豁免）。</td></tr><tr><td><code>domain → application</code> / <code>domain → data</code></td><td>禁止。需要能力就在 domain 抽接口。</td></tr></tbody></table><p><code>application → data</code> 仅三类豁免：Drift 句柄传递、原生 SQL 事务、<code>CourseDatabase</code> 本地句柄构造，走逐文件白名单。白名单是双向校验的，既拦未授权导入，也报「已豁免但不再导入，去删豁免项」。</p><p>领域模型不依赖 Flutter Widget。共享词汇（主题 token、状态模型、结果枚举）放 <code>core</code> 或 <code>domain</code>，不写在页面文件里。</p><h2 id="命名与选型" tabindex="-1">命名与选型 <a class="header-anchor" href="#命名与选型" aria-label="Permalink to &quot;命名与选型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>既定选型</th><th>不得写成</th></tr></thead><tbody><tr><td>状态与结果建模</td><td><code>sealed class</code> + pattern matching</td><td>enum + if 链</td></tr><tr><td>多返回值</td><td>record <code>(a, b)</code></td><td>一次性 DTO / <code>Map&lt;String, dynamic&gt;</code></td></tr><tr><td>领域模型</td><td>freezed + <code>part</code>，改动后 <code>make gen</code></td><td>手写 <code>==</code> / <code>copyWith</code> / <code>toJson</code></td></tr><tr><td>依赖注入</td><td>injectable 注解 + get_it</td><td>手写 <code>GetIt.register*</code></td></tr><tr><td>路由</td><td>auto_route 注解</td><td>手写 <code>MaterialPageRoute</code></td></tr><tr><td>具名工具类</td><td><code>abstract final class</code></td><td>可实例化 class 承载静态方法</td></tr></tbody></table><p>页面文件统一 <code>*_page.dart</code>，新代码不得新增 <code>_screen.dart</code>。组件目录：跨功能共享放 <code>lib/views/widgets/</code>，功能域私有放 <code>&lt;feature&gt;/components/</code>，新功能域统一用 <code>components/</code>。</p><h2 id="状态管理" tabindex="-1">状态管理 <a class="header-anchor" href="#状态管理" aria-label="Permalink to &quot;状态管理&quot;">​</a></h2><p>状态选型三段：UI 局部状态用 <code>setState</code>；跨 widget 共享用 <code>provider</code>（<code>ChangeNotifier</code> + <code>context.watch/read</code>）；无 UI 依赖的服务 / 仓库用 <code>get_it</code>。</p><p>Provider + ChangeNotifier 承担状态广播。复杂功能拆分为专用 provider，<code>GameProvider</code> 等 facade 只负责聚合和转发，不复制状态。</p><p><strong>页面里不得直接 <code>getIt&lt;DataLayerType&gt;()</code></strong>；数据访问一律走 repository 接口或 application 门面。</p><p>并发状态必须显式表示。例如复习评分使用 in-flight 集合阻止评分与撤销竞态，AI 使用取消令牌和幂等键控制在途请求。</p><p>全应用 LLM 出入口唯一是 <code>lib/application/ai/engine/</code>，页面不得直连任何 LLM SDK。</p><p>日志统一走 <code>core/logger.dart</code> 的 <code>logger</code>，禁 <code>print</code>（analyzer 强制）与 <code>debugPrint</code>（仅自觉）。空 catch 必须有一行注释说明为何安全。</p><h2 id="依赖注入" tabindex="-1">依赖注入 <a class="header-anchor" href="#依赖注入" aria-label="Permalink to &quot;依赖注入&quot;">​</a></h2><p>GetIt 与 Injectable 注册 renderer、service 和 repository。生成文件由 <code>build_runner</code> 产生并提交。新增注解后需要重新生成；普通业务代码修改不需要。</p><h2 id="路由" tabindex="-1">路由 <a class="header-anchor" href="#路由" aria-label="Permalink to &quot;路由&quot;">​</a></h2><p>全屏页面使用 Auto Route。<code>CourseReadyGuard</code> 在课程数据库未准备完成时重定向到启动页。底部主 Tab 使用 IndexedStack，不伪装为 push/pop 路由。</p><p>平台默认：</p><ul><li>Android：Material 路由和预测返回。</li><li>iOS / macOS：Cupertino 路由和边缘返回。</li><li>Web：无页面转场。</li></ul><p>调用点不直接构造任意 <code>MaterialPageRoute</code>、<code>CupertinoPageRoute</code> 或自定义 PageRouteBuilder。</p><h2 id="渲染插件" tabindex="-1">渲染插件 <a class="header-anchor" href="#渲染插件" aria-label="Permalink to &quot;渲染插件&quot;">​</a></h2><p>14 种 Interaction renderer 通过 Injectable 注册（<code>di/renderer_module.dart</code>），分发走 <code>lib/views/lesson/components/interactions/interaction_renderer.dart</code> 的 <code>lookupRenderer()</code>。它先用 <code>_handlesTypeFor()</code> 把实例映射到 freezed 公开接口类型再匹配——<strong>不能直接用 <code>runtimeType</code></strong>，因为 freezed 生成的是私有 <code>_$FooImpl</code>，永远不等于渲染器声明的 <code>handlesType</code>。</p><p><code>ankiHtmlCard</code> 在课时体内的渲染器是退役占位（<code>AnkiHtmlCardRetiredRenderer</code>）；Official 复习的保真渲染走 <code>anki_official/</code> 自己的路径。新增题型需要同时修改：</p><ol><li>领域 union / 序列化。</li><li>renderer（并在 module 登记）。</li><li>DI 生成（重跑 <code>make gen</code>，无需改动分发逻辑）。</li><li>Python 与 Dart validator。</li><li>JSON 示例和测试。</li><li>文档。</li></ol><h2 id="ai-边界" tabindex="-1">AI 边界 <a class="header-anchor" href="#ai-边界" aria-label="Permalink to &quot;AI 边界&quot;">​</a></h2><p><code>application/ai/engine/</code> 是唯一 LLM 流量出口。引擎只暴露 chat 与结构化请求；课程、提示、SRS 和教材导入分别持有领域 Prompt 和解析规则。</p><h2 id="anki-边界" tabindex="-1">Anki 边界 <a class="header-anchor" href="#anki-边界" aria-label="Permalink to &quot;Anki 边界&quot;">​</a></h2><p>Android 生产 Official-first 路径位于 <code>application/anki_official/</code>。Collection 与 scheduler 拥有正式卡片状态。Legacy 路径已整体退役（v1 读路径与 course.db 内的 <code>anki_notetypes</code> / <code>anki_notes</code> / <code>anki_cards_meta</code> 三表均已删除），只剩受控迁移，不是生产自动降级。</p><blockquote><p><strong>状态限定</strong>：Official Anki 当前口径是「验收 NO-GO；迁移中」。Android 写侧仅在真机以 <strong>debug 构建</strong>验证过，<strong>生产 bundle 尚未验证</strong>；iOS 仅有模拟器 E2E。不得写「迁移完成」或「Android 可正常使用」。权威状态见应用仓库 <code>docs/official-anki-migration/34-cutover-receipt.md</code>。</p></blockquote><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/developer/local-data">本地数据模型</a></li><li><a href="/docs/developer/testing">测试与质量门禁</a></li><li><a href="/docs/guide/features">核心能力一览</a></li></ul>`,39)])])}const g=a(n,[["render",i]]);export{u as __pageData,g as default};
